+// Parses an optional whole-number query param. Returns undefined when absent,
+// NaN when present but not a whole number in [min, max].
+function wholeParam(params, name, min, max) {
+  if (!params.has(name)) return undefined;
+  const raw = params.get(name);
+  if (!/^\d+$/.test(raw)) return NaN;
+  const n = Number(raw);
+  return n >= min && n <= max ? n : NaN;
+}
